    capture_sensor sensor;
    int is_simulated;
    capture_state state;
    uint64_t tick;
    int64_t scheduled_mono_ns;     /* this tick's deadline */
    uint32_t last_sequence;        /* 0: no attempt has completed */
    uint32_t consecutive_failures;
    uint64_t attempts;
    uint64_t failures;
    uint64_t missed_ticks;
    uint64_t next_attempt_tick;
    int sensor_initialized;
} capture_heartbeat;

/*
 * Where devices and time come from.
 * - open_device follows i2c_linux_open's contract.
 * - read_clock returns 0 or the errno of the failed read.
 * - sleep_until sleeps to an absolute CLOCK_MONOTONIC deadline and returns
 *   0, EINTR (the core checks stop_requested and sleeps again), or another
 *   errno (fatal).
 * - check_clock_trust returns the trust state; on UNKNOWN it sets *err.
 * - stop_requested returns nonzero once shutdown was requested.
 * - is_simulated labels output produced before the device is open.
 */
typedef struct {
    i2c_result (*open_device)(void *ctx, i2c_device *dev,
                              unsigned bus_number, uint8_t address_7bit,
                              int *cleanup_errno);
    int (*read_clock)(void *ctx, capture_clock clock, struct timespec *out);
    int (*sleep_until)(void *ctx, int64_t deadline_mono_ns);
    capture_clock_trust (*check_clock_trust)(void *ctx, int *err);
    int (*stop_requested)(void *ctx);
    void *ctx;
    int is_simulated;
} capture_env;

/*
 * Where results go; the future hub connection. Each callback returns 0 or
 * an errno. PROVISIONAL: any failure is fatal, since what to do while the
 * hub is unreachable depends on the IPC design.
 */
typedef struct {
    int (*emit_sample)(void *ctx, const capture_sample *sample);
    int (*emit_heartbeat)(void *ctx, const capture_heartbeat *heartbeat);
    void *ctx;
} capture_sink;

/*
 * How a run ended. exit is the FIRST fatal failure; a later close failure
 * never replaces it. The close result is kept separately in close_io, so
 * neither error is lost; a failed close turns an otherwise clean stop into
 * CAPTURE_EXIT_CLOSE_FAILED.
 */
typedef struct {
    capture_exit exit;
    int exit_errno;          /* errno behind exit, or 0 */
    i2c_result open_io;      /* the open result, when an open was tried */
    int open_cleanup_errno;
    int close_attempted;
    i2c_result close_io;     /* meaningful when close_attempted */
} capture_outcome;

/*
 * Fill *cfg with the PROPOSED values for sensor: a 10 s tick, light every
 * tick or soil every 6 ticks, backoff cap 8, both reinitialization
 * triggers on (rejections: 3), first_sequence 1.
 */
void capture_config_proposed(capture_config *cfg, capture_sensor sensor,
                             unsigned bus_number, uint8_t address_7bit);

/*
 * Run until a stop is requested or a fatal failure. Returns the same value
 * as out->exit. USAGE returns before anything is opened or emitted; *out
 * is always written when out is not NULL. Every device opened here is
 * closed before returning.
 */
capture_exit capture_run(const capture_config *cfg, const capture_env *env,
                         const capture_sink *sink, capture_outcome *out);

/* Stable text for logs, e.g. "DEGRADED". */
const char *capture_state_name(capture_state state);
const char *capture_exit_name(capture_exit exit);

#endif
#ifndef SENSORS_CAPTURE_LINUX_H
#define SENSORS_CAPTURE_LINUX_H

#include "sensors/capture.h"

/*
 * Real Linux seams for capture_run (sensors/capture.h):
 * - read_clock: clock_gettime(CLOCK_REALTIME or CLOCK_MONOTONIC).
 * - sleep_until: clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME), so an
 *   interrupted sleep resumes toward the same deadline. EINTR is passed
 *   back for capture_run to check the stop flag.
 * - check_clock_trust: docs/design.md "Clock trust". adjtimex() with
 *   modes = 0 (read-only); the clock is trusted only when the call does
 *   not return TIME_ERROR and STA_UNSYNC is clear. A failed call is
 *   CAPTURE_CLOCK_TRUST_UNKNOWN with its errno, which the design treats as
 *   untrusted. Checked fresh on every call, never cached.
 * - open_device: i2c_linux_open (opens a real /dev/i2c-N).
 * - stop_requested: a flag set by the SIGTERM/SIGINT handler below.
 *
 * capture_linux_env does not install the handlers; a capture program calls
 * capture_linux_install_stop_handlers first. Only a capture program uses
 * these seams; there is no such program yet.
 */

/*
 * Install a handler for SIGTERM and SIGINT that only sets the stop flag,
 * with no sigaction flags: a blocked sleep returns EINTR, and the handler
 * stays installed for a second signal. Returns 0 or the errno of the
 * failed sigaction; if SIGINT fails, the SIGTERM handler stays installed
 * (the caller should exit).
 */
int capture_linux_install_stop_handlers(void);

/* Fill *env with the real seams; is_simulated is 0 and ctx is internal. */
void capture_linux_env(capture_env *env);

#endif
#ifndef SENSORS_CAPTURE_ARGS_H
#define SENSORS_CAPTURE_ARGS_H

#include "sensors/capture.h"

#include <stdio.h>

/*
 * Command-line options for the future capture program: one program, run
 * as two processes (one per sensor). These options do not depend on the
 * capture-to-hub interface, which is not agreed yet, so there are no
 * output or socket options here.
 *
 *   --sensor light|soil  required
 *   --bus N              required; no default, because init writes to the
 *                        bus (BH1750 Power On, soil software reset)
 *   --addr ADDR          light 0x23 (default) or 0x5c; soil 0x36 (default)
 *                        to 0x39
 *   --tick-ms N          PROPOSED 10000; 100 to 3600000
 *   --every N            ticks between attempts; PROPOSED light 1, soil 6;
 *                        1 to 1000
 *   --help
 *
 * Numbers are decimal; addresses may also be hex (0x23). Options may not
 * repeat, and a value may not start with "--". Arguments are checked in
 * order, so --help wins only when no earlier argument is an error (as in
 * sensor-diag). Every other capture_config field keeps its proposed value
 * (capture_config_proposed).
 */

#define CAPTURE_ARGS_TICK_MS_MIN 100u
#define CAPTURE_ARGS_TICK_MS_MAX 3600000u
#define CAPTURE_ARGS_EVERY_MAX   1000u

typedef enum {
    CAPTURE_ARGS_RUN,    /* *cfg is filled in */
    CAPTURE_ARGS_HELP,   /* --help was given */
    CAPTURE_ARGS_ERROR   /* an error was printed to err */
} capture_args_result;

/* Parse argv. On RUN *cfg is written; otherwise it is untouched. */
capture_args_result capture_parse_args(int argc, char *const argv[],
                                       capture_config *cfg, FILE *err);

/* Usage text, marking the rates as proposals. */
void capture_usage(FILE *out, const char *program);

/*
 * Process exit status for a run's result: 0 for STOPPED, 2 for USAGE and
 * 1 for every failure. PROVISIONAL until the supervisor's needs are
 * agreed; the program also logs capture_exit_name.
 */
int capture_exit_status(capture_exit result);

#endif
#ifndef SENSORS_CAPTURE_LOG_H
#define SENSORS_CAPTURE_LOG_H

#include "sensors/capture.h"

#include <stdio.h>

/*
 * Text log lines for a capture process: one line per sample, heartbeat
 * and exit, for people reading the log and for evidence. This is NOT the
 * capture-to-hub message format and NOT the heartbeat protocol; neither
 * is agreed yet.
 *
 * Every line starts with SIMULATED or LIVE (from the sample's, the
 * heartbeat's or the caller's is_simulated) and is key=value text:
 * - sample: sequence, tick, phase, validity, value with an explicit unit
 *   (value=none when invalid, never 0), light raw_count, driver stage,
 *   transport status and errno (with errno_text), the requested and
 *   transferred lengths for a short transfer (docs/design.md keeps those
 *   out of the record), the rejected value, both timestamps (none plus
 *   the errno when unavailable) and the clock trust.
 * - heartbeat: the capture_heartbeat fields.
 * - exit: the exit reason and errno (with errno_text), and the open and
 *   close results, or not_attempted.
 *
 * Out-of-range enums print UNKNOWN (phase, unit) or INVALID (clock
 * trust), never a real value; a missing stage name prints stage=none.
 *
 * Each function writes and flushes one line, then returns 0, or EIO if
 * the flush fails or the stream's error indicator is set. A stream that
 * was already in error makes every later call return EIO. The pointers
 * must not be NULL.
 */

int capture_log_sample(FILE *out, const capture_sample *sample);

int capture_log_heartbeat(FILE *out, const capture_heartbeat *heartbeat);

int capture_log_exit(FILE *out, capture_sensor sensor, int is_simulated,
                     const capture_outcome *outcome);

/* Stable text: "light" or "soil" ("unknown" otherwise). */
const char *capture_sensor_name(capture_sensor sensor);

#endif

