    capture_config_proposed(&want, CAPTURE_SENSOR_LIGHT, 1, 0x23);
    assert(same_config(&cfg, &want) && err_bytes == 0);

    assert(parse(soil, &cfg, &err_bytes) == CAPTURE_ARGS_RUN);
