/*
 * Tests for the capture program's options. No device, clock or bus is
 * used; parsing only.
 */

#define COUNT_OF(a) (sizeof(a) / sizeof((a)[0]))

static char last_err[512];   /* the error text of the last parse() */

/* parse: run the parser on a NULL-terminated list; keep its error text. */
static capture_args_result parse(char *const *args, capture_config *cfg,
                                 long *err_bytes)
{
    char *argv[20];
    int argc = 0;
    FILE *err = tmpfile();
    capture_args_result r;
    size_t n;

    assert(err != NULL);
    argv[argc++] = "capture";
    while (*args != NULL) {
        assert(argc < (int)COUNT_OF(argv) - 1);
        argv[argc++] = *args++;
    }
    argv[argc] = NULL;
    r = capture_parse_args(argc, argv, cfg, err);
    assert(fflush(err) == 0);
    *err_bytes = ftell(err);
    rewind(err);
    n = fread(last_err, 1, sizeof last_err - 1, err);
    assert(!ferror(err));
    last_err[n] = '\0';
    assert(fclose(err) == 0);
    return r;
}

