#define _POSIX_C_SOURCE 200809L
/* macOS hides mkdtemp in strict POSIX mode; Linux ignores this. */
#define _DARWIN_C_SOURCE

#include "storage/log_writer.h"
#include "storage/record.h"
#include "../src/storage/log_writer_sys.h"

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#ifdef NDEBUG
#error "tests rely on assert; do not build them with NDEBUG"
#endif

/*
 * Two kinds of test. Every record is built by the test; none is a
 * measurement, and no sensor is used.
 * - FILE: real syscalls against a fresh directory from mkdtemp, removed at
 *   the end. These check what actually reaches the file.
 * - SIMULATED: a fake syscall table scripts failures and records every
 *   call, so each error path runs deterministically.
 */


static char temp_dir[PATH_CAP];

/* make_temp_dir: create a fresh, empty directory for one test. */
static void make_temp_dir(void)
{
    const char *base = getenv("TMPDIR");
    int n;

    if (base == NULL || base[0] == '\0')
        base = "/tmp";
    n = snprintf(temp_dir, sizeof temp_dir, "%s/storage-log-test.XXXXXX",
                 base);
    assert(n > 0 && (size_t)n < sizeof temp_dir);
    assert(mkdtemp(temp_dir) != NULL);
}

/* file_path: write temp_dir/name into buf. */
static void file_path(char *buf, size_t size, const char *name)
{
    int n = snprintf(buf, size, "%s/%s", temp_dir, name);

    assert(n > 0 && (size_t)n < size);
}

/* remove_temp_file: delete temp_dir/name. */
static void remove_temp_file(const char *name)
{
    char path[PATH_CAP];

    file_path(path, sizeof path, name);
    assert(unlink(path) == 0);
}

/* remove_temp_dir: delete the (now empty) temporary directory. */
static void remove_temp_dir(void)
{
    assert(rmdir(temp_dir) == 0);
}

/* read_file: read all of temp_dir/name into buf; return its length. */
#include "sensors/capture_log.h"

#include <errno.h>
#include <inttypes.h>
#include <string.h>

/* label: the prefix every log line starts with. */
static const char *label(int simulated)
{
    return simulated ? "SIMULATED" : "LIVE";
}

/* unit_name: the explicit unit of a sample's value; UNKNOWN if invalid. */
static const char *unit_name(capture_unit unit)
{
    switch (unit) {
    case CAPTURE_UNIT_MILLILUX:
        return "millilux";
    case CAPTURE_UNIT_RAW_COUNTS:
        return "raw_counts";
    default:
        return "UNKNOWN";
    }
}

/* phase_name: which driver call gave a sample's stage; UNKNOWN if invalid. */
static const char *phase_name(capture_phase phase)
{
    switch (phase) {
    case CAPTURE_PHASE_INIT:
        return "INIT";
    case CAPTURE_PHASE_MEASURE:
        return "MEASURE";
    default:
        return "UNKNOWN";
    }
}

/*
 * trust_name: stable text for a clock-trust result. UNKNOWN means the
173: * capture_log_exit: how the run ended, with the open and close results.
174- * capture_run zeroes the outcome, so a zero open result alone does not
175- * mean the open succeeded. A successful open is always followed by a
176- * close attempt; a failed one leaves a non-OK result; otherwise no open
177- * was attempted (USAGE, or a clock, sink or stop exit before the open).
178- */
179:int capture_log_exit(FILE *out, capture_sensor sensor, int is_simulated,
180-                     const capture_outcome *o)
181-{
182-    fprintf(out, "%s sensor=%s event=exit result=%s",
183-            label(is_simulated), capture_sensor_name(sensor),
184-            capture_exit_name(o->exit));
185-    print_errno(out, "errno", o->exit_errno);
186-    if (o->close_attempted || o->open_io.status != I2C_STATUS_OK) {
187-        fprintf(out, " open=%s open_errno=%d cleanup_errno=%d",
188-                i2c_status_name(o->open_io.status), o->open_io.os_errno,
189-                o->open_cleanup_errno);
190-    } else {
191-        fputs(" open=not_attempted open_errno=none cleanup_errno=none", out);
192-    }
193-    if (o->close_attempted) {
194-        fprintf(out, " close=%s close_errno=%d\n",
195-                i2c_status_name(o->close_io.status), o->close_io.os_errno);
196-    } else {
197-        fputs(" close=not_attempted close_errno=none\n", out);
198-    }
199-    return finish(out);
200-}

